-- ============================================================
-- SEED EXT 6: Módulo 10 — Basic Modals (ex 225-300)
-- Tópicos: deduction/certainty, obligation/advice, ability/possibility,
-- modais em contextos formais, TOEFL integrado avançado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'modais-basicos';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo modais-basicos não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Modais de dedução e certeza (must, can't, might, could)
  (cid,71,225,'gap_fill','_____ correlation _____ (not/be) _____ sufficient to _____ (establish) _____ causation — there _____ (must/be) _____ underlying _____ mechanism that _____ (explain) _____ relationship before _____ (draw) _____ causal _____ conclusion.','A / is not / sufficient / establish / causation / must be / an / underlying / explains / the / drawing / a / causal',NULL,'''Must be'' = logical necessity + inferential reasoning in research methodology.','medium'),
  (cid,71,226,'gap_fill','_____ findings _____ (might/explain) _____ anomaly that _____ (observe/passive) in _____ previous _____ studies, or there _____ (could/be) _____ confounding _____ variable that _____ (not/yet/identify/passive) and that _____ (skew) _____ results in _____ (both/cases).','The / might explain / the / was observed / the / previous / could be / a / confounding / has not yet been identified / that / skews / the / both',NULL,'''Might/could'' = epistemic possibility for unexplained anomaly.','medium'),
  (cid,71,227,'gap_fill','Given _____ consistency of _____ data across _____ multiple _____ independent _____ samples, _____ (it/can''t/be) _____ mere _____ coincidence — there _____ (must/be) _____ systematic _____ factor _____ (drive) _____ pattern _____ (observe/passive).','the / the / multiple / independent / it can''t be / a / mere / must be / a / systematic / driving / the / observed',NULL,'''Can''t be'' (logical impossibility) + ''must be'' (logical necessity) for strong inference.','medium'),
  (cid,71,228,'gap_fill','_____ effect size _____ (could/smaller/prove) in _____ real-world _____ settings than in _____ controlled _____ laboratory _____ conditions — _____ (this) _____ (mean) that _____ (the/intervention) _____ (might/not/as effective/prove) when _____ (scale/passive).','The / could prove smaller / real-world / than / controlled / this could mean / the intervention / might not prove as effective / scaled',NULL,'''Could'' + ''might not prove'' for hedged real-world effectiveness prediction.','hard'),
  (cid,71,229,'gap_fill','Something _____ (must/wrong/go) during _____ implementation phase — _____ outcomes _____ (cannot/reflect) _____ quality of _____ intervention as _____ (design) because _____ (they) _____ (inconsistent/too/be) with _____ prior _____ evidence _____ (support) its _____ effectiveness.','must have gone wrong / the / the / cannot reflect / the / designed / they / are too inconsistent / the / prior / supporting',NULL,'''Must have gone wrong'' (past deduction) + ''cannot reflect'' (logical impossibility).','hard'),
  (cid,71,230,'multiple_choice','Which modal BEST expresses a logical deduction in academic writing?','The concentration levels found in the samples must indicate prolonged exposure, as occasional contact could not produce such elevated readings.','["The concentration levels found in the samples should indicate prolonged exposure.","The concentration levels found in the samples might indicate prolonged exposure.","The concentration levels found in the samples must indicate prolonged exposure, as occasional contact could not produce such elevated readings.","The concentration levels found in the samples will indicate prolonged exposure."]','''Must indicate'' = logical necessity; ''could not produce'' = logical impossibility. Together: strongest academic deduction.','medium'),
  (cid,71,231,'gap_fill','_____ pattern _____ (could/explain/passive) by _____ (three/at least) _____ competing _____ hypotheses, and _____ current _____ evidence _____ (not/sufficient/be) to _____ (distinguish) _____ definitively _____ between them — further _____ investigation _____ (be) _____ (clearly) _____ necessary.','The / could be explained / at least three / competing / the / current / is not sufficient / distinguish / definitively / is clearly necessary',NULL,'''Could be explained'' + ''is not sufficient'' for multiple hypothesis situation.','medium'),
  (cid,71,232,'gap_fill','_____ authors _____ (cannot/rule out) _____ possibility that _____ (select/bias) _____ (influence/passive) _____ results, though _____ (they) _____ (note) that _____ steps _____ (take/passive) to _____ (minimize) it and that _____ (direction/likely/be) toward _____ (conservative/an) _____ estimate.','The / cannot rule out / the / selection bias / has influenced / the / they / note / the / were taken / minimize / the / is likely / toward / a conservative',NULL,'''Cannot rule out'' + epistemic hedge about bias direction.','hard'),

  -- BLOCK 72: Modais de obrigação, conselho, permissão
  (cid,72,233,'gap_fill','_____ researchers _____ (must/obtain) _____ (inform/passive) _____ consent from _____ all _____ participants before _____ (begin) _____ data _____ collection — _____ (this) _____ (non-negotiable/be) _____ regardless of _____ (whether) _____ (they) _____ (consider) _____ risk _____ minimal.','The / must obtain / informed / consent / all / beginning / data / this is non-negotiable / regardless / they / consider / the / minimal',NULL,'''Must obtain'' = absolute obligation in research ethics.','medium'),
  (cid,72,234,'gap_fill','_____ institutions _____ (should/establish) _____ clear _____ protocols for _____ (handle) _____ conflicts of _____ interest — not merely _____ (require/passive) that they _____ (disclose/passive) but _____ (ensure) that _____ (disclosure) _____ (trigger) _____ meaningful _____ review process.','The / should establish / clear / handling / the / merely required / be disclosed / ensuring / disclosure / triggers / a / meaningful',NULL,'''Should establish'' + corrective elaboration of ''not merely...but.''','hard'),
  (cid,72,235,'gap_fill','_____ (author) _____ (may/not/use) _____ (copyright/material/protect) without _____ (permission) from _____ rights _____ holder, though _____ (fair use) _____ doctrine _____ (permit) _____ limited _____ quotation for _____ purposes of _____ (criticism) and _____ commentary.','Authors / may not use / copyright-protected / without / permission / the / the / fair use / doctrine / permits / limited / for / criticism',NULL,'''May not'' (prohibition) + ''permits'' for copyright rule.','medium'),
  (cid,72,236,'gap_fill','Having _____ (identify) _____ gap in _____ literature, _____ researchers _____ (ought to/address) it through _____ (rigorous) _____ empirical _____ work rather than _____ (content) themselves with _____ (point) out its _____ existence — _____ (scholarship/advance) by _____ (do), not _____ by _____ (identify).','identified / the / the / ought to address / rigorous / contenting / pointing / scholarship advances / doing / identifying',NULL,'''Ought to address'' + corrective contrast with ''rather than.''','medium'),
  (cid,72,237,'gap_fill','_____ government _____ (must) not _____ (use) _____ emergency _____ powers in ways that _____ (exceed) _____ scope _____ (authorize/passive) by _____ enabling _____ legislation — _____ courts _____ (shall/be) _____ independent _____ arbiter of _____ whether _____ (executive/action) _____ (within/remain) _____ (constitutional/bound).','The / must not / use / emergency / exceed / the / authorized / the / enabling / the / shall be / the / independent / of / executive action / remains within / constitutional bounds',NULL,'''Must not'' (prohibition) + ''shall be'' (obligation) in constitutional law language.','hard'),
  (cid,72,238,'multiple_choice','Which modal is MOST APPROPRIATE in an academic recommendation?','Policymakers should consider the distributional consequences of any reform before implementation, not merely its aggregate efficiency gains.','["Policymakers must consider the distributional consequences.","Policymakers could consider the distributional consequences.","Policymakers should consider the distributional consequences of any reform before implementation, not merely its aggregate efficiency gains.","Policymakers can consider the distributional consequences."]','''Should'' = strong recommendation without the absolute force of ''must.'' Appropriate for policy advice.','easy'),
  (cid,72,239,'gap_fill','_____ (author/this) _____ (argue) that _____ regulator _____ (need to) _____ (balance) _____ (competing) _____ objectives _____ (carefully) — _____ (simply/to/not) _____ (maximize) one _____ at _____ expense of _____ other but _____ (to/find) _____ arrangement that _____ (acceptable/prove) across _____ range of _____ relevant _____ dimensions.','The author of this / argues / the / needs to / balance / competing / carefully / not simply to / maximize / the / at the expense of / to find / an / proves acceptable / a / relevant',NULL,'''Needs to balance'' + corrective ''not simply to maximize.''','hard'),
  (cid,72,240,'gap_fill','_____ (all/parties) _____ (must) _____ (ensure) that _____ (their) _____ (representative) _____ (appropriate/authorise/passive) to _____ (enter) _____ into _____ (binding) _____ commitments on _____ (their/behalf) before _____ talks _____ (commence) — _____ negotiating _____ time _____ (too/valuable/be) to _____ (waste) on _____ (subsequently/invalidate/passive) _____ agreements.','All parties / must / ensure / their / representatives / are appropriately authorised / enter / binding / their behalf / the / commence / negotiating / is too valuable / waste / subsequently invalidated',NULL,'''Must ensure'' + ''too valuable to waste'' for pre-negotiation authorization requirement.','hard'),

  -- BLOCK 73: Modais de habilidade e possibilidade (can, could, be able to)
  (cid,73,241,'gap_fill','_____ (technology) _____ (enable) _____ analysis at _____ scale that _____ (was/previously/impossible) — researchers _____ (can/now/process) _____ datasets _____ containing _____ billions of _____ (observation) that _____ (overwhelm) _____ capacity of _____ earlier _____ methods.','The / enables / an / that / was previously impossible / can now process / datasets / observations / would have overwhelmed / the / earlier',NULL,'''Can now process'' = new capability enabled by technology.','medium'),
  (cid,73,242,'gap_fill','Not _____ (all) _____ (challenge) _____ (address/passive) through _____ technological _____ means alone — _____ (some) _____ (require) _____ (institutional) _____ change and _____ political _____ will that _____ (technology/by itself/cannot/provide).','all / challenges / can be addressed / technological / means / some / require / institutional / political / technology by itself cannot provide',NULL,'''Can be addressed'' + ''cannot provide'' for technology limits argument.','medium'),
  (cid,73,243,'gap_fill','_____ cross-disciplinary _____ collaboration _____ (enable) _____ researchers to _____ (tackle) _____ problems that _____ (would/resistant/prove) to _____ approaches _____ (confine) to _____ single _____ disciplinary _____ perspective — _____ complexity of _____ contemporary _____ challenges _____ (demand/this).','Cross-disciplinary / enables / to / tackle / would prove resistant / single-disciplinary / confined / a / this / the / demands / this',NULL,'''Enable'' + ''would prove resistant'' for cross-disciplinary collaboration rationale.','medium'),
  (cid,73,244,'gap_fill','_____ (committee) _____ (be able to/reach) _____ _____ (consensus) only if _____ (all) _____ (member) _____ (willing/be) to _____ (prioritize) _____ collective _____ outcome over _____ (their) _____ (individual) _____ preferences — _____ (condition) that _____ (frequently/prove) _____ (difficult) to _____ (sustain).','The / was able to reach / a / consensus / all / members / were willing / prioritize / the / their / individual / a / condition / frequently proves / difficult / sustain',NULL,'''Was able to reach'' + conditional clause for consensus condition.','medium'),
  (cid,73,245,'gap_fill','With _____ (sufficient) _____ political _____ will and _____ (institutional) _____ support, _____ (reform/of/this/kind) _____ (implement/passive) within _____ (current/political/cycle) — but without _____ (these), even _____ (best-designed) _____ measures _____ (will/fail) _____ to _____ (achieve) _____ (intended/their) _____ impact.','sufficient / political / institutional / reform of this kind / can be implemented / the current political cycle / without / the / best-designed / will fail / achieve / their intended',NULL,'''Can be implemented'' + ''will fail'' for political will conditionality.','hard'),
  (cid,73,246,'gap_fill','_____ (critics) _____ (argue) that _____ (technology) _____ (cannot/substitute) for _____ (genuine) _____ (human) _____ judgment in _____ (high-stake) _____ decisions — that _____ (algorithm) _____ (process) _____ (pattern) but _____ (cannot/understand) _____ (context) and _____ nuance that _____ (require) to _____ (apply) _____ rule _____ wisely.','Critics / argue / technology / cannot substitute / genuine / human / judgment / high-stakes / algorithms / can process / patterns / cannot understand / the / context / are required / apply / a / wisely',NULL,'''Cannot substitute/understand'' for human judgment argument.','hard'),
  (cid,73,247,'gap_fill','_____ (country) _____ (potentially/increase) _____ energy _____ security by _____ (diversify) _____ supply _____ sources — but _____ (this) _____ (require) _____ (substantial) _____ investment and _____ (political/sustained/commitment) that _____ (historically/prove) _____ (difficult) to _____ (maintain) over _____ long _____ (time/horizon).','The / can potentially increase / energy / by / diversifying / supply / this requires / substantial / sustained political commitment / has historically proved / difficult / maintain / a / long / time horizon',NULL,'''Can potentially increase'' + hedged obligation for energy security argument.','medium'),
  (cid,73,248,'multiple_choice','Which sentence MOST effectively uses ''could'' to express a past ability?','The negotiators could not reach agreement during the first session but managed to do so in the second.','["The negotiators couldn''t reach agreement during the first session.","The negotiators could not reach agreement during the first session but managed to do so in the second.","The negotiators were not able to reach agreement during the first session but could do so in the second.","The negotiators could not reach agreement."]','''Could not...but managed to do so'' = failed ability + eventual success, complete thought with contrast.','easy'),

  -- BLOCK 74: Modais em contextos formais e jurídicos
  (cid,74,249,'gap_fill','_____ (contracting/parties) _____ (shall) _____ (fulfill) _____ (their) _____ respective _____ obligations as _____ (set forth) in _____ Schedule A, and _____ (failure) to _____ (do) so _____ (shall/constitute) _____ material _____ breach _____ (entitle) _____ (non-defaulting) _____ party to _____ (seek) _____ remedies _____ (set forth) in _____ Clause 14.','The contracting parties / shall / fulfill / their / respective / set forth / the / failure / do / shall constitute / a / material / entitling / the / non-defaulting / seek / the / set forth / Clause',NULL,'''Shall'' = legal obligation; ''shall constitute'' = legal consequence in contract language.','hard'),
  (cid,74,250,'gap_fill','_____ court _____ (may/award) _____ damages only where _____ (claimant) _____ (establish) _____ (on the balance of probabilities) that _____ (they) _____ (suffer) _____ loss _____ (directly/cause/passive) by _____ (defendant''s) _____ breach — _____ (mere) _____ breach _____ (insufficient/be) without _____ (demonstrable) _____ harm.','The / may award / the / claimant / has established / on the balance of probabilities / they / have suffered / a / directly caused / the / defendant''s / mere / is insufficient / demonstrable',NULL,'''May award'' (judicial permission/discretion) + ''is insufficient'' for damages standard.','hard'),
  (cid,74,251,'gap_fill','_____ signatory _____ states _____ (shall) _____ (report) to _____ secretariat _____ (annually) on _____ (their) _____ progress toward _____ (implementing) _____ (undertaking) _____ (assume/passive) under _____ this _____ convention, and _____ reports _____ (shall/make/passive) _____ publicly _____ available _____ (no later than) _____ sixty _____ days _____ (after) _____ (submission).','The / signatory / shall / report / the / annually / their / implementing / the / undertakings / assumed / the / those / shall be made / publicly / available / no later than / sixty / after / submission',NULL,'''Shall report'' + ''shall be made publicly available'' in multilateral treaty language.','hard'),
  (cid,74,252,'gap_fill','_____ (member/state) _____ (may/reserve) _____ right to _____ (apply) _____ (more/stringent) _____ standards than _____ (those) _____ (require/passive) by _____ (this/directive), provided that _____ (such) _____ measures _____ (not/constitute) _____ disguised _____ restriction on _____ (freedom) of _____ movement _____ (goods).','Member states / may reserve / the / apply / more stringent / those / required / this / such / do not constitute / a / disguised / the / freedom / movement of goods',NULL,'''May reserve'' (permission) + ''do not constitute'' (condition) in EU directive language.','hard'),
  (cid,74,253,'multiple_choice','Which modal is MOST APPROPRIATE in formal legal drafting?','The arbitral tribunal shall issue its award within ninety days of the close of proceedings.','["The arbitral tribunal should issue its award within ninety days.","The arbitral tribunal must issue its award within ninety days.","The arbitral tribunal shall issue its award within ninety days of the close of proceedings.","The arbitral tribunal will issue its award within ninety days."]','''Shall'' is the standard modal of legal obligation in contracts and legal instruments. ''Must'' is increasingly used but ''shall'' remains dominant in formal drafting.','medium'),
  (cid,74,254,'gap_fill','_____ regulatory _____ authority _____ (may/require) _____ (applicant) to _____ (provide) _____ additional _____ information and _____ (can/suspend) _____ review _____ clock pending _____ (receipt) of such _____ information — _____ period _____ (suspension) _____ (shall/not/count) toward _____ statutory _____ deadline.','The / regulatory / may require / the / applicant / provide / additional / can suspend / the / receipt / such / the / of / suspension / shall not count / the / statutory',NULL,'''May require'' + ''can suspend'' + ''shall not count'' in regulatory procedure.','hard'),
  (cid,74,255,'gap_fill','Where _____ (national) _____ law _____ (not/provide) _____ adequate _____ remedy for _____ (breach) of _____ (the/rights) _____ (guarantee) under _____ (this/convention), _____ (individual/state/party) _____ (may/bring) _____ complaint to _____ commission, which _____ (shall/examine) it in _____ accordance with _____ (its) _____ established _____ procedures.','national / does not provide / an / adequate / breach / the rights / guaranteed / this / an individual or state party / may bring / a / the / shall examine / accordance / its / established',NULL,'''May bring'' (permission/right) + ''shall examine'' (obligation) in human rights convention.','hard'),
  (cid,74,256,'gap_fill','_____ (disclosing/party) _____ (must/not) _____ (use) _____ confidential _____ information for _____ any _____ purpose other than _____ (evaluate) _____ (propose/passive) _____ transaction and _____ (shall/return) or _____ (destroy) all _____ material _____ (contain) such _____ information upon _____ written _____ request _____ from _____ (disclosing/party).','The / disclosing party / must not / use / the / any / evaluating / the / proposed / shall return / destroy / all / containing / such / the / from / the / disclosing party',NULL,'''Must not use'' + ''shall return/destroy'' in NDA confidentiality obligation.','hard'),

  -- BLOCK 75: TOEFL Reading com modais
  (cid,75,257,'multiple_choice','[TOEFL Reading] ''Scientists suggest that the phenomenon could be explained by changes in ocean current patterns.'' The word ''could'' indicates:','A possible, but not certain, explanation that scientists are considering.','["Certainty about the explanation","A past ability","A possible, but not certain, explanation that scientists are considering.","An obligation to explain"]','''Could be explained'' = epistemic possibility; scientists are not certain, only suggesting.','easy'),
  (cid,75,258,'gap_fill','[TOEFL Reading] ''The findings _____ (significant/prove) for _____ (develop) _____ more effective _____ (treatment), though _____ researchers _____ (caution) that _____ (further) _____ clinical _____ trials _____ (must/conduct/passive) before _____ (any) _____ clinical _____ application _____ (consider/passive).'' Best forms?','could prove significant / for / developing / more / treatments / the / caution / further / clinical / must be conducted / any / clinical / application / is considered',NULL,'''Could prove'' (possibility) + ''must be conducted'' (obligation) in research reading.','medium'),
  (cid,75,259,'gap_fill','[TOEFL Reading] ''_____ (this/policy) _____ (address/passive) _____ (this/issue) _____ effectively, it _____ (need/passive) to _____ (complement/passive) by _____ broader _____ (structural) _____ reforms — without which _____ (it) _____ (treat) _____ (symptoms) rather than _____ (cause).'' Best forms?','For this policy to address / this issue / effectively / needs to be complemented / broader / structural / it will treat / symptoms / causes',NULL,'''Needs to be complemented'' + predictive ''will treat'' for policy reading.','medium'),
  (cid,75,260,'gap_fill','[TOEFL Reading] ''_____ (implementation) of _____ (measure/this) _____ (should/phased) _____ to _____ (allow) _____ stakeholders _____ (adapt) gradually — an _____ (abrupt) _____ transition _____ (could/prove) _____ (disruptive) to _____ (existing) _____ (arrange) and _____ (generate) _____ unintended _____ consequences.'' Best forms?','The / implementation / this measure / should be phased / allow / stakeholders / to adapt / abrupt / could prove / disruptive / existing / arrangements / generate / unintended',NULL,'''Should be phased'' (recommendation) + ''could prove'' (possibility) in reading analysis.','medium'),
  (cid,75,261,'gap_fill','[TOEFL Reading] ''Not _____ (observation/all) _____ that _____ (seem) _____ (consistent) with _____ (theory) _____ (necessarily/confirm) it — they _____ (explain/also/passive) by _____ competing _____ theories, and _____ (this/alone/not/distinguish) _____ between _____ (them).'' Best forms?','all / observations / seem / consistent / the / necessarily confirm / could also be explained / competing / this alone cannot distinguish / them',NULL,'''Necessarily confirm'' + ''could be explained'' + ''cannot distinguish'' for confirmation bias reading.','hard'),
  (cid,75,262,'multiple_choice','[TOEFL Reading] ''The proposed solution may address the symptoms but cannot resolve the underlying structural causes.'' Which paraphrase is MOST ACCURATE?','The solution might help with surface-level issues but lacks the capacity to fix the deeper problems.','["The solution will definitely fix all problems.","The solution is unable to do anything useful.","The solution might help with surface-level issues but lacks the capacity to fix the deeper problems.","The solution should not be implemented."]','''May address'' = possible help + ''cannot resolve'' = definite inability to fix root causes.','easy'),
  (cid,75,263,'gap_fill','[TOEFL Reading] ''_____ mechanism _____ (appear) to _____ (operate) differently at _____ (large/scale), which _____ (mean) that _____ (findings) from _____ (small) _____ studies _____ (not/necessarily/generalize/passive) to _____ real-world _____ contexts where _____ (intervention) _____ (deploy/passive) at _____ population _____ scale.'' Best forms?','The / appears / operate / large scale / means / the / small / cannot necessarily be generalized / real-world / the / is deployed / population',NULL,'''Cannot necessarily be generalized'' for scale limitation.','hard'),
  (cid,75,264,'gap_fill','[TOEFL Reading] ''_____ (any) _____ (final) _____ assessment _____ (premature/be) at _____ (this) _____ stage — _____ (long-term) _____ data _____ (available/not/yet/be) and _____ definitive _____ conclusions _____ (draw/passive) only when _____ (full) _____ dataset _____ (analyze/passive).'' Best forms?','Any / final / assessment / would be premature / this / long-term / data / are not yet available / can be drawn / the full / is analyzed',NULL,'''Would be premature'' + ''are not yet'' + ''can be drawn only when'' for premature conclusion warning.','medium'),

  -- BLOCK 76: TOEFL Speaking com modais
  (cid,76,265,'production','[TOEFL Speaking — 45s] A reading argues cities should adopt specific transport policies. Summarize using modals.','',NULL,'The reading argues that cities should prioritize investment in public transportation systems as a central strategy for reducing urban congestion and emissions, and that this approach can deliver multiple benefits simultaneously that car-centric approaches cannot achieve. The reading notes that well-designed metro systems can move significantly more passengers per hour than road infrastructure of equivalent cost, which means cities should not simply expand road capacity when they face congestion, since this will only generate additional demand. The reading also argues that cities must integrate land use planning with transport investment, because transport systems can only function effectively if the density and mix of uses around stations makes walking and cycling viable. The reading concludes that cities that fail to make these investments now will find themselves locked into car dependence that becomes increasingly difficult to reverse as urban form adapts to the car-centric infrastructure, and that this lock-in will make the task of reducing emissions far more expensive in the future than addressing it proactively now would be.','hard'),
  (cid,76,266,'production','[TOEFL Speaking — 45s] A professor discusses whether artificial intelligence should replace human decision-making in medicine.','',NULL,'The professor argues that artificial intelligence should be understood as a tool that can augment human medical decision-making rather than replace it, because the two can do different things well and the combination can achieve better outcomes than either alone. She explains that AI systems can process enormous quantities of data and can identify patterns that human physicians might miss, particularly in domains like medical imaging where pattern recognition across thousands of cases is required. However, she argues that AI systems currently cannot adequately handle the contextual reasoning, ethical judgment, and communication with patients that effective medical practice requires. She gives the example of a diagnostic algorithm that might correctly identify a cancer but cannot determine whether a patient would choose aggressive treatment given their values and circumstances, and cannot have the conversation that would allow a patient to make an informed decision. The professor concludes that the appropriate question is not whether AI should replace physicians but how medical training and practice must adapt to ensure physicians can effectively use AI tools while maintaining the human judgment that patients need.','hard'),
  (cid,76,267,'production','[TOEFL Speaking — 60s] A reading and lecture discuss whether economic growth must come at the expense of environmental protection. Use modals throughout.','',NULL,'The reading argues that the assumed trade-off between economic growth and environmental protection may be less fundamental than is commonly believed, and that well-designed policy can achieve both simultaneously. The reading notes that clean technology industries can generate significant economic activity and employment while reducing emissions, and that regulatory standards can drive innovation that creates competitive advantages for domestic firms. The reading also argues that the costs of environmental damage, including health costs from pollution and productivity losses from climate-related disruption, must be counted against the benefits of growth, and that growth that destroys the natural capital on which future production depends cannot be considered genuinely beneficial. The professor agrees with the reading''s general argument but adds important qualifications. She argues that while environmental and economic goals need not be fundamentally opposed, the political economy of transition is genuinely difficult. Workers in carbon-intensive industries cannot simply be told that clean industries will eventually generate equivalent employment, because the transition will impose concentrated costs that may fall on workers and communities that will not automatically benefit from new clean industries. She argues that governments must therefore pair environmental policy with active support for affected workers and regions if they are to build the political coalitions needed to sustain the transition. She concludes that the answer to the reading''s question is yes — growth and environmental protection can be compatible — but only if governments manage the distributional consequences of the transition and build the political support required to sustain it.','hard'),
  (cid,76,268,'gap_fill','[TOEFL Speaking] _____ professor _____ (argue) that _____ (this/approach) _____ (help) _____ address _____ problem but _____ (not/be) _____ sufficient on _____ (its/own) — _____ additional _____ measures _____ (also/need/passive) if _____ goals _____ (achieve/passive) within _____ timeframe _____ (specify/passive).','The / argues / this approach / can help / address / the / will not be / sufficient / its own / additional / will also be needed / the / are to be achieved / the / specified',NULL,'''Can help'' + ''will not be sufficient'' + ''will also be needed'' in academic commentary.','medium'),

  -- BLOCK 77: TOEFL Writing com modais
  (cid,77,269,'production','[TOEFL Writing — 200 words] Write a paragraph arguing that governments should prioritize long-term investment over short-term popularity.','',NULL,'Governments should prioritize long-term investment in public goods over short-term measures designed primarily to maximize electoral popularity, even though the political incentives push strongly in the opposite direction. The reason is straightforward: the investments that societies most need — in education, research, infrastructure, public health, and environmental protection — typically generate their highest returns over periods that extend well beyond any single electoral cycle, which means governments that discount the long term too heavily will systematically underinvest in them. A government that must demonstrate results within a four-year term will find it difficult to justify the allocation of scarce resources to programs whose benefits cannot be clearly demonstrated before the next election, even when the long-term returns are high and the cost of not making the investment is even higher. This creates a structural bias toward short-term spending that must be corrected through institutional mechanisms — independent fiscal institutions, long-term investment frameworks, cross-party agreements on core public goods — that can sustain investment commitments through changes in government. Countries that have managed this successfully, including those that have maintained strong positions in education, research, and infrastructure over multiple decades, demonstrate that the institutional design challenge is not insurmountable. The political will to address it must be generated, however, and this requires leaders who can articulate a compelling vision of the long-term public interest that citizens find worth supporting.','hard'),
  (cid,77,270,'production','[TOEFL Writing — 200 words] Write a paragraph on what governments should and should not do in response to technological unemployment.','',NULL,'Governments should respond to technological unemployment through active labor market policies, educational investment, and social protection reform, and should not attempt to slow or prevent the technological change that is causing it. The reason governments should not try to halt technological change is that it cannot ultimately be prevented — firms and countries that adopt productivity-enhancing technology will outcompete those that do not, meaning that protecting workers from automation in one country will simply shift both the automation and the associated productivity gains elsewhere. What governments can and should do is ensure that the gains from technological change are broadly shared and that workers who are displaced by automation can access the support and retraining they need to participate in the labor market of the future. This means governments should reform educational and training systems to develop skills that complement rather than compete with automation, including the higher-order cognitive and interpersonal skills that automated systems currently cannot replicate. It also means governments should redesign social protection systems to cover workers whose employment patterns do not fit the employment-based insurance models designed for a different era of work. What governments must avoid is the politically tempting response of promising that displaced workers can return to the jobs they held before — they should instead help workers build the capabilities needed for the jobs that will actually be available.','hard'),
  (cid,77,271,'production','[TOEFL Writing — 200 words] Write a paragraph on what institutions must do to maintain public trust.','',NULL,'Institutions must earn and maintain public trust through consistent performance, transparency, and accountability, and they cannot substitute public relations for the substantive behaviors that trust requires. The fundamental requirement is performance: institutions must deliver the outcomes they are established to achieve, and they cannot maintain trust indefinitely if they persistently fail to do so, regardless of how effectively they communicate. Beyond performance, institutions must be transparent about their decisions and the reasoning behind them, because citizens in democratic societies will not accept indefinitely an instruction to trust institutions that refuse to explain themselves. Transparency alone is not sufficient if it is not accompanied by genuine accountability — institutions must be subject to oversight mechanisms that can identify and correct failures, and these mechanisms must be capable of actually imposing consequences rather than merely identifying problems. Institutions should also engage proactively with their critics and with those who raise concerns about their performance, not because critics are always right but because the engagement may identify problems that internal processes have missed and because the willingness to engage signals confidence rather than defensiveness. What institutions must not do is treat public trust as a communications challenge to be managed rather than a performance standard to be met — citizens can generally distinguish between institutions that work and those that merely try to appear to work, and the gap between appearance and reality will ultimately damage trust more severely than honest acknowledgment of limitations would.','hard'),
  (cid,77,272,'gap_fill','[TOEFL Writing] What institutions _____ (do) is _____ (equally) _____ as _____ important as what they _____ (must/do) — _____ constraints on _____ (power) _____ (as/function/important/serve) as _____ grants of _____ authority, and _____ (institution/well-design) _____ (attend) to _____ (both).','should not / equally / must do / the / serve as important a function / grants / authority / a / well-designed / attends / both',NULL,'''Should not do/must do'' paired with ''serve as important a function'' for institutional design argument.','hard'),

  -- BLOCK 78: TOEFL Writing — sínteses avançadas
  (cid,78,273,'production','[TOEFL Writing — 200 words] Write a paragraph synthesizing a reading and lecture on whether artificial intelligence can replace human creativity.','',NULL,'The reading and lecture together suggest that while artificial intelligence can increasingly replicate the outputs of creative processes, it cannot replicate the cognitive and experiential conditions that make human creativity valuable, and that this distinction should shape how we think about the role of AI in creative fields. The reading notes that AI systems can now generate text, music, and visual art that is often indistinguishable from human-produced work in surface characteristics, and argues that this capability may prove transformative for industries that depend on the production of creative content at scale. The professor accepts this point but argues it misunderstands what is most valuable about human creativity. She argues that the value of human creativity does not lie primarily in the output but in the process: in the fact that creative work expresses a perspective shaped by lived experience, engages with the conditions and concerns of a particular moment, and communicates something about human experience that only a human could have created. If a poem could have been generated by an AI, the professor argues, this does not mean that a human-generated poem has no additional value — it means we must be clearer about what that additional value is and why it matters. She concludes that AI should be understood as a tool that can amplify and support human creativity, not as a replacement for the creative capacity that only humans can bring, and that creative fields should use AI to handle the aspects of creative work that are primarily technical while preserving the human judgment that gives creative work its meaning.','hard'),
  (cid,78,274,'production','[TOEFL Writing — 200 words] Write a body paragraph arguing that trade agreements must include enforceable labor standards.','',NULL,'Trade agreements must include enforceable labor standards if they are to avoid creating incentives for a race to the bottom in worker protection, and the experience of agreements without such standards provides ample evidence of why this matters. When trade agreements lower tariffs and other barriers to trade without establishing minimum labor standards, they create incentives for the low-wage partner to attract investment by keeping standards low and for the high-wage partner to face pressure to weaken its standards to remain competitive. The result can be a dynamic in which the expansion of trade comes at the expense of worker wellbeing rather than contributing to the broadly shared prosperity that trade agreements are intended to generate. Proponents of agreements without labor standards argue that such agreements should focus narrowly on trade barriers and that labor standards should be addressed through separate mechanisms. This argument might be credible if separate mechanisms existed and were effective, but in most cases they do not. The practical consequence of excluding labor standards from trade agreements is therefore that they are not effectively addressed at all. Trade agreements should include labor provisions that meet international standards, include monitoring mechanisms that can identify violations, and include remedies that can be effectively enforced — not as a favor to workers in high-wage countries seeking to protect their jobs but as a basic condition for trade relationships that distribute their benefits fairly.','hard'),
  (cid,78,275,'gap_fill','[TOEFL Writing] _____ (argument) _____ (make/passive) in _____ (reading) _____ (not/accept/passive) _____ (uncritically) — _____ (there) _____ (be) _____ competing _____ considerations that _____ (acknowledge/passive) and _____ (weigh) _____ carefully before _____ (drawing) _____ conclusions about _____ (which) _____ approach _____ (should/adopt/passive).','The / argument / made / the / should not be accepted / uncritically / there / are / competing / must be acknowledged / weighed / drawing / which / approach / should be adopted',NULL,'''Should not be accepted'' + ''must be acknowledged/weighed'' + ''should be adopted'' in critical academic response.','hard'),
  (cid,78,276,'gap_fill','[TOEFL Writing] Both _____ (reading) and _____ (lecture) _____ (suggest) that _____ (problem) _____ (address/passive) urgently, but _____ (they) _____ on _____ (question) of how — _____ (lecturer) _____ (argue) that _____ approach _____ (recommend/passive) in _____ (reading) _____ (produce) _____ unintended _____ consequences and that _____ alternative _____ (try/passive) first.','the / reading / the / lecture / suggest / the / must be addressed / they disagree / the / the / lecturer / argues / the / recommended / the / will produce / an / alternative / should be tried',NULL,'''Must be addressed'' + ''will produce'' + ''should be tried'' for reading-lecture synthesis.','hard'),

  -- BLOCK 79: Exercícios avançados com modais compostos
  (cid,79,277,'gap_fill','_____ (review) _____ (evidence), _____ (researchers) _____ (conclude) that _____ (effect) _____ (must/larger/be) than _____ (initially/report/passive) — _____ original _____ (sample) _____ (too/small/have/been) to _____ (detect) it _____ (reliable/passive), and _____ (larger) _____ (studies) _____ (subsequently/confirm) this _____ (suspicion).','Having reviewed / the evidence / the / concluded / the / effect / must be larger / initially reported / the / sample / must have been too small / detect / reliably / larger / have subsequently confirmed / this',NULL,'''Must be larger'' + ''must have been too small'' for retrospective inference chain.','hard'),
  (cid,79,278,'gap_fill','_____ (interpretation) _____ (cannot/correct/be) in _____ (light) of _____ (evidence) that _____ (subsequently/emerge) — if _____ (it/were), _____ (we) _____ (expect) to _____ (observe) _____ pattern _____ (consistent) with it, but _____ (what/observe/passive) is _____ (precisely) _____ (opposite).','This / cannot be correct / the / light / the / subsequently emerged / it were / we / would expect / observe / a / consistent / what / is observed / precisely / the opposite',NULL,'''Cannot be correct'' + ''would expect'' + ''is observed'' for logical elimination.','hard'),
  (cid,79,279,'gap_fill','_____ (decision) _____ (have/take/passive) _____ into _____ (consideration) _____ interests of _____ all _____ (affect/passive) parties — _____ (narrow) _____ (process) that _____ (exclude/passive) key _____ (stakeholder) _____ (produce) _____ decisions that _____ (resist/passive) _____ (subsequently).','The / should have taken / consideration / the / affected / a / narrow / that / excluded / stakeholders / will produce / are subsequently resisted',NULL,'''Should have taken'' (past obligation not met) + ''will produce'' for process critique.','hard'),
  (cid,79,280,'multiple_choice','Which modal construction MOST effectively expresses a past recommendation that was not followed?','The committee should have consulted affected communities before finalizing the design, but proceeded without doing so.','["The committee must consult affected communities before finalizing the design.","The committee should consult affected communities before finalizing the design.","The committee should have consulted affected communities before finalizing the design, but proceeded without doing so.","The committee could have consulted affected communities."]','''Should have consulted'' = past obligation not met + ''but proceeded without'' confirms non-compliance.','easy'),
  (cid,79,281,'gap_fill','_____ (problem) _____ (tackle/passive) through _____ (comprehensive) _____ package of _____ (complement) measures — no _____ (single) _____ intervention _____ (sufficient/be) on _____ (its/own), and _____ (piecemeal) _____ approaches _____ (risk) _____ (address) _____ some _____ aspects of _____ issue while _____ (neglect) _____ others.','The / must be tackled / a / comprehensive / complementary / single / will be sufficient / its own / piecemeal / risk / addressing / neglecting',NULL,'''Must be tackled'' + ''will be sufficient'' + ''risk addressing/neglecting'' for comprehensive approach argument.','hard'),
  (cid,79,282,'gap_fill','_____ (stakeholder/this) _____ (cannot/have/act) in _____ good _____ faith — _____ (conduct) _____ (demonstrate/passive) throughout _____ (proceeding) _____ (inconsistent) with _____ (commitment) they _____ (ostensibly/make/passive).','This stakeholder / cannot have acted / good / faith / their / conduct / as demonstrated / throughout / the proceedings / is inconsistent / the / commitments / ostensibly made',NULL,'''Cannot have acted'' = logical impossibility of past good faith based on evidence.','hard'),

  -- BLOCK 80: Exercícios finais de produção
  (cid,80,283,'production','[TOEFL Writing — 200 words] Write a final synthesis on what must change for multilateral institutions to be effective.','',NULL,'Multilateral institutions must undergo significant reform if they are to remain effective in addressing the global challenges of the twenty-first century, and the obstacles to such reform, while real, need not be insurmountable. The most fundamental change that must occur is a reform of the distribution of voting rights and representation in major institutions to reflect the current distribution of economic and political weight, rather than the distribution that prevailed when the institutions were founded. Institutions that cannot claim to represent the world as it is today will find their legitimacy declining among the emerging powers whose cooperation is increasingly necessary for effective global governance. Beyond representational reform, institutions must develop the capacity to address challenges — including climate change, digital governance, and pandemic preparedness — that were not anticipated when they were designed, and that do not fit neatly into the mandates of institutions organized around the priorities of the mid-twentieth century. This may require creating new bodies where existing ones cannot be adapted, or significantly expanding the mandates of existing institutions. Institutions should also develop more effective mechanisms for engaging non-state actors — including civil society organizations, the private sector, and technical communities — whose knowledge and resources are increasingly necessary for addressing global challenges but whose participation current institutional designs do not adequately accommodate. Reform on this scale can only happen if the major powers that control the current institutions conclude that the benefits of effective multilateralism exceed the costs of sharing influence — a conclusion that recent trends have made less certain but that remains achievable if the right arguments are made persuasively.','hard'),
  (cid,80,284,'production','[TOEFL Speaking — 60s] The reading argues that social media must be regulated; the professor argues it should regulate itself. Discuss.','',NULL,'The reading argues that social media platforms must be subject to external government regulation because they have demonstrated that they cannot be trusted to regulate themselves in ways that adequately protect users and democratic processes. The reading notes that platforms have repeatedly prioritized engagement and revenue over user safety and information quality, and that the incentive structures they face will not change unless external regulation creates enforceable requirements. Without such regulation, the reading argues, platforms will continue to allow misinformation to spread, will fail to protect vulnerable users from harmful content, and will continue to collect and use personal data in ways that users have not meaningfully consented to. The professor challenges this argument on practical grounds. She argues that the complexity and pace of change in social media make effective government regulation extremely difficult to design and implement. Regulators often cannot understand the technologies they are trying to regulate well enough to write rules that will achieve their intended effects without creating unintended consequences, and by the time regulations can be developed and enacted, the technology will have changed in ways that make them obsolete. The professor argues that a better approach would be to require platforms to be more transparent about how their systems work, to give users more meaningful controls over their experience, and to be held accountable for specific demonstrable harms — rather than attempting comprehensive regulation that will likely fail to keep pace with technological change.','hard'),
  (cid,80,285,'gap_fill','If _____ (reform) _____ (should/succeed), it _____ (must) _____ (build) _____ (a/broad) _____ coalition of _____ (support) that _____ (can/sustain) _____ opposition of _____ (those) _____ who _____ (benefit) from _____ (status quo) — _____ (this) _____ (require) _____ political _____ skill that _____ (rare/be) and that _____ (not/take/passive) for _____ granted.','the / is to succeed / must / build / a / broad / support / can sustain / the / those / who benefit / the / this / requires / political / is rare / should not be taken / granted',NULL,'''Must build'' + ''can sustain'' + ''requires'' + ''should not be taken'' for reform condition.','hard'),
  (cid,80,286,'gap_fill','_____ (institutions/all) _____ (eventually/face) _____ moment when _____ (they) _____ (choose) between _____ (genuine) _____ adaptation and _____ (self-protective) _____ inertia — and _____ (choice) _____ (make) at _____ that _____ moment _____ (determine) whether _____ they _____ (survive) and _____ (thrive) or _____ (decline) into _____ (irrelevance).','All institutions / eventually face / a / they / must choose / genuine / self-protective / the / made / will determine / whether / they / survive / thrive / decline / irrelevance',NULL,'''Must choose'' + ''will determine'' for institutional adaptation turning point.','medium'),
  (cid,80,287,'gap_fill','_____ (lesson) _____ that _____ (repeat/passive) _____ across _____ (history) of _____ (governance) is _____ (simple) but _____ (often/prove) _____ (difficult) to _____ (internalize): _____ (institutions) _____ (that/serve) _____ well _____ (those) _____ (that/design/passive) with _____ (clear/sense) of _____ (purpose), _____ (adequate) _____ (resource), and _____ genuine _____ (accountability) to _____ (those) they _____ (ostensibly/serve/passive).','The / lesson / repeated / across / the / governance / simple / often proves / difficult / internalize / institutions / serve / well / are / those / designed / a / clear sense / purpose / adequate / resources / those / are ostensibly served',NULL,'''Serve well'' + ''designed with'' + ''ostensibly served'' for institutional lesson.','hard'),
  (cid,80,288,'gap_fill','_____ (challenges) that _____ (ahead/lie) _____ (not/beyond/be) _____ capacity of _____ (the/international/community) to _____ (address) — but _____ (addressing/they) _____ (will/require) _____ commitment to _____ (collective) _____ action that _____ (not/yet/demonstrate/passive) at _____ scale _____ required.','The / lie ahead / are not beyond / the capacity / the / address / addressing them / will require / a / collective / has not yet been demonstrated / the / required',NULL,'''Are not beyond'' + ''will require'' + ''has not yet been demonstrated'' for cautious optimism conclusion.','hard'),
  (cid,80,289,'production','[TOEFL Writing — 200 words] Final capstone paragraph: synthesize what must, should, can, and cannot be done to address a major global challenge.','',NULL,'The challenge of sustainable development requires that we be clear about what must be done, what should be done, what can be done, and what cannot be done — because conflating these categories has contributed to persistent gaps between ambition and achievement. What must be done is non-negotiable: the global economy must reduce net carbon emissions to zero by mid-century, critical ecosystems must be preserved, and the billions of people who currently lack adequate food, clean water, healthcare, and education must have access to them. These are not optional preferences but requirements for a livable and just world. What should be done is a question of priority among many legitimate goals: governments should invest heavily in clean technology, should redesign social protection systems to cover the workers displaced by the necessary economic transition, and should reform international financial architecture to mobilize the capital needed for developing countries to pursue sustainable development. What can be done depends on the resources, institutions, and political conditions of particular contexts — and honest analysis must acknowledge that what is achievable varies enormously across countries and circumstances. What cannot be done is pretend that good intentions substitute for the institutional capacity, political will, and financial resources that implementation requires. The failure to be honest about this distinction — to commit to outcomes without addressing the conditions for achieving them — is among the most persistent sources of the gap between what sustainable development promises and what it delivers.','hard'),
  (cid,80,290,'gap_fill','In _____ (end), _____ (progress) _____ (possible/be) — but it _____ (will/depend) on _____ choices that _____ (make/passive) by _____ (those/office) and those who _____ (hold/them/account). _____ (past) _____ (shown/have) that _____ (this/of/kind) _____ progress _____ (achieve/passive); _____ (question) _____ (be) whether _____ (will) _____ (there/be) to _____ (achieve) it.','the end / progress / is possible / will depend / the / are made / those in office / hold them to account / the past / has shown / this kind of / can be achieved / the question / is / the will / will be there / achieve',NULL,'''Is possible/will depend/can be achieved/will be there'' for final optimistic conditional conclusion.','medium'),
  (cid,80,291,'gap_fill','_____ (those/come) _____ after _____ will _____ (judge) _____ (us) not by _____ (aspiration) _____ (articulate/passive) but by _____ (action) _____ (take/passive) — and by _____ (action) _____ (should/take/passive) but _____ (not/were).','Those who come / after / judge / us / the / aspirations / articulated / the / actions / taken / the / actions / should have been taken / were not',NULL,'''Should have been taken but were not'' = past obligation not met in generational accountability.','hard'),
  (cid,80,292,'production','[TOEFL Writing — 200 words] Final synthesis essay conclusion on what must be done and what should be avoided in international cooperation.','',NULL,'The analysis in this essay has sought to identify both what must be done if international cooperation is to deliver the outcomes that current global challenges require, and what must be avoided if cooperative efforts are not to be undermined by the dynamics that have historically limited them. What must be done is clear in broad outline, even if the details are contested: institutions that reflect the current distribution of global influence must be built and sustained, financing for global public goods must be mobilized at the scale the problems require, and the domestic political foundations for sustained international engagement must be cultivated in the major powers whose participation is indispensable. What must be avoided is equally clear: the temptation to allow short-term political pressures to override long-term cooperative commitments, the tendency to create institutions without providing them with the resources and authority needed to be effective, and the mistake of treating international agreements as ends in themselves rather than as means to the outcomes they are intended to achieve. What should be recognized is that progress has been made before in circumstances that seemed unpromising — that the institutional architecture that exists today would not have seemed achievable from the perspective of those who built it — and that what can be built in the future is not limited by what has been achieved in the past. The question is not whether better international cooperation is possible. History shows that it can be. The question is whether the political will to build it will be sustained long enough to make it real.','hard'},
  (cid,80,293,'gap_fill','We _____ (cannot) _____ (afford) to _____ (fail) at _____ this — _____ consequences _____ (simply) _____ too _____ grave. But we _____ (also/cannot) _____ (afford) to _____ (pretend) that _____ good _____ intentions _____ (substitute) for _____ (the) _____ (institutional) _____ capacity and _____ (the) _____ political _____ will that _____ (actually/require) to _____ (make) _____ progress.','We / cannot / afford / fail / the / are simply / too / we also cannot / afford / pretend / good / intentions / can substitute / the / institutional / the / political / are actually required / make / real',NULL,'''Cannot afford to fail'' + ''cannot afford to pretend'' for urgent double negative imperative.','medium'),
  (cid,80,294,'production','[TOEFL Speaking — 60s] Summarize what the reading says institutions should do and what the professor says they must not do.','',NULL,'The reading and the professor''s lecture present complementary perspectives on institutional design that together define both positive requirements and important prohibitions. The reading argues that effective institutions should be designed with clear mandates that specify what they are supposed to achieve, should have the resources needed to pursue those mandates, should have accountability mechanisms that create genuine incentives for performance, and should be able to adapt their methods as circumstances change. The reading emphasizes that institutions should be evaluated on outcomes — on whether they actually achieve their mandates — rather than on procedural compliance or internal process measures that may not correlate with the results that matter. The professor adds an important set of prohibitions. She argues that institutions must not conflate their own survival with the pursuit of their mandate — one of the most common pathologies of institutions is that they become primarily oriented toward perpetuating themselves rather than achieving the purposes for which they were established. Institutions must not treat the populations they serve as means to institutional ends rather than as the reason for the institution''s existence. And institutions must not insulate themselves from accountability by claiming that their work is too technical or too complex to be assessed by non-specialists — this claim, even when partly true, is too easily used to avoid the scrutiny that accountability requires. Together, the reading and professor suggest that what institutions should do and must not do are two sides of the same coin: institutions that pursue their mandates with adequate resources and genuine accountability will, by definition, avoid the pathologies the professor identifies.','hard'),
  (cid,80,295,'gap_fill','_____ (institutions) that _____ (survive) and _____ (thrive) over _____ (long) _____ periods _____ (those/are) that _____ (learn) from _____ (mistake) and _____ (adapt) — _____ (cannot) _____ _____ (which) _____ (do) so _____ (destined/are) to _____ (repeat) _____ (same) _____ mistakes and _____ (find) _____ (themselves) _____ (increasingly) _____ (misaligned) with _____ (needs) _____ they _____ (ostensibly/serve).','Institutions / survive / thrive / long / are those / learn / mistakes / adapt / those which cannot / are destined / repeat / the same / find / themselves / increasingly / misaligned / the / they / ostensibly serve',NULL,'''Are destined to repeat'' + ''find themselves misaligned'' for institutional adaptation argument.','hard'),
  (cid,80,296,'gap_fill','It _____ (seem) _____ (paradox) that _____ (institutions/strongest) _____ (those/are) that _____ (willing/most/be) to _____ (acknowledge) _____ (their) _____ own _____ (limitation) — but _____ (paradox) _____ (resolve) when one _____ (recognizes) that _____ (acknowledgment) _____ (prerequisite/is) for _____ (learning) and _____ (adaptation) that _____ (resilience/sustain).','may seem / a paradox / the / strongest institutions / are those / most willing / acknowledge / their / limitations / the / resolves / recognizes / acknowledgment / is a prerequisite / the / learning / adaptation / sustain / resilience',NULL,'''May seem a paradox'' + ''resolves'' + ''is a prerequisite'' for institutional learning argument.','hard'),
  (cid,80,297,'gap_fill','_____ (challenge/greatest) _____ that _____ (institutions/any) _____ (face) _____ (not/is) _____ (those/external/the) but _____ (those/internal) — _____ (tendency) to _____ (become) _____ (comfortable) with _____ (own/their) _____ (routine), to _____ (resist) _____ (change) even when _____ (evidence) _____ (clear) that _____ (change) _____ (necessary).','The greatest challenges / any / institutions / face / are not the external ones / the internal ones / the tendency / become / comfortable / their own / routines / resist / the / is clear / is necessary',NULL,'''Are not the external'' + ''the internal'' for institutional internal challenge paradox.','medium'),
  (cid,80,298,'gap_fill','We _____ (must/acknowledge) _____ (that) _____ (progress) _____ (not/automatic), that _____ (institution/good) _____ (not/sufficient), and that _____ (what/we/can/achieve) _____ (will/depend) ultimately on _____ (the/choices) _____ (make) by _____ (the/people/in/position) to _____ (make) them.','must acknowledge / that / progress / is not automatic / good institutions / are not sufficient / what we can achieve / will depend / the choices / made / the people in position / make',NULL,'''Must acknowledge'' + ''is not automatic/sufficient'' + ''will depend'' for realistic assessment.','medium'),
  (cid,80,299,'production','[TOEFL Writing — 200 words] Final paragraph: what modals reveal about the nature of academic argument.','',NULL,'The modal verbs that pervade academic writing — must, should, can, cannot, may, might, could — are not mere grammatical decorations but carry the weight of the epistemic and normative commitments that make academic argument meaningful. When scholars write that evidence must be interpreted in a particular way, they are making a claim about logical necessity. When they argue that researchers should follow certain procedures, they are making a normative claim about good practice. When they note that certain conclusions can be drawn from available data, they are making a claim about what the evidence permits, which is different from what it requires. When they acknowledge that certain outcomes might occur, they are signaling appropriate uncertainty about futures that are genuinely contingent. Getting these modals right is not a minor matter of linguistic precision — it is a matter of intellectual honesty. The scholar who uses ''must'' when only ''might'' is warranted is overstating the evidence. The one who uses ''might'' when ''must'' is justified is understating it. Both errors distort the epistemic relationship between evidence and conclusion that is the foundation of scholarly credibility. Learning to use modal verbs with precision is therefore not merely a language skill — it is a component of the broader intellectual discipline of saying neither more nor less than the evidence warrants, which is the core obligation of any scholar who takes seriously the responsibility of contributing to knowledge.','hard'),
  (cid,80,300,'production','[TOEFL Writing — Final capstone 200 words] Concluding paragraph: synthesize what modals express about obligation, possibility, and recommendation in academic writing.','',NULL,'Academic writing uses modal verbs to navigate the complex territory between what is, what must be, what should be, what can be, and what might be — and the precision with which these distinctions are made is a measure of the quality of the thinking behind them. When a scholar argues that a particular policy must be adopted, they are making a claim about necessity that requires strong supporting argument; if the evidence supports only a recommendation, ''should'' is more appropriate, and the scholar who uses the stronger modal bears a higher burden of justification. When empirical claims are made, the modals must accurately reflect the strength of the evidence: ''the data demonstrate that X must be true'' is very different from ''the data suggest that X may be true,'' and the difference is not stylistic but substantive. The range of modal verbs available to academic writers is in this sense a resource for intellectual precision — a set of tools for calibrating the strength of claims to the strength of the evidence and reasoning that support them. The discipline required to use these tools well is inseparable from the discipline required to think well: the writer who is unclear about what their evidence supports will be unable to choose the right modal, while the writer who has thought carefully about the strength of their argument will find that the right modal is the one that most accurately expresses it. In the end, the modal verbs of academic writing are the grammar of epistemic responsibility.','hard')

